using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TasiaCraft;

public static class ResizeTest {
 static string root,log; static int passed; static LivePreview preview;
 static readonly JavaScriptSerializer json=new JavaScriptSerializer();
 static void Require(bool ok,string name){if(!ok)throw new Exception(name);passed++;File.AppendAllText(log,"PASS "+name+Environment.NewLine);}
 static void Near(double actual,double expected,string name){Require(Math.Abs(actual-expected)<.00001,name+" ("+actual+" expected "+expected+")");}
 static void Same(Point actual,Point expected,string name){Require((actual-expected).Length<.00001,name+" ("+actual+" expected "+expected+")");}
 static void Reject(Action action,string name){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(InvalidDataException){rejected=true;}Require(rejected,name);}
 static void Fixture(string path,int w,int h,bool split){using(var b=new System.Drawing.Bitmap(w,h)){using(var g=System.Drawing.Graphics.FromImage(b)){g.Clear(split?System.Drawing.Color.Red:System.Drawing.Color.Lime);if(split)g.FillRectangle(System.Drawing.Brushes.Blue,w/2,0,w/2,h);}b.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
 static Border Layer(){return preview.Stage.Children.OfType<Border>().Last();}
 // Inspect the compositor's actual transformed crop geometry, independent of resize implementation.
 static Point Grip(int x,int y){preview.UpdateLayout();var box=Layer();var bounds=box.Clip.Bounds;return box.TransformToAncestor(preview.Stage).Transform(new Point(x==0?bounds.Left:x==2?bounds.Right:(bounds.Left+bounds.Right)/2,y==0?bounds.Top:y==2?bounds.Bottom:(bounds.Top+bounds.Bottom)/2));}
 static Project Setup(Media source,Media green,Clip clip,int w,int h){var p=new Project{Width=w,Height=h};p.Media.Add(green);p.Media.Add(source);p.Clips.Add(new Clip{MediaId=green.Id,Duration=1});clip.MediaId=source.Id;clip.Duration=1;clip.Track=1;p.Clips.Add(clip);preview.SetProject(p);preview.Seek(.2);preview.UpdateLayout();return p;}
 static bool IsColor(byte[] p,int width,int x,int y,int channel){int n=(y*width+x)*4;return p[n+channel]>180&&p[n+(channel+1)%3]<75&&p[n+(channel+2)%3]<75;}
 static byte[] PreviewPixels(int w,int h){preview.UpdateLayout();var target=new RenderTargetBitmap(w,h,96,96,PixelFormats.Pbgra32);target.Render(preview.Stage);var bytes=new byte[w*h*4];target.CopyPixels(bytes,w*4,0);return bytes;}
 static byte[] ExportPixels(Project p,string name){string output=Path.Combine(root,name+".mp4"),image=Path.Combine(root,name+".png");Engine.Render(p,output,null);Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(output)+" -frames:v 1 -threads 1 "+Engine.Quote(image));using(var b=new System.Drawing.Bitmap(image)){Require(b.Width==p.Width&&b.Height==p.Height,name+" export dimensions");var bytes=new byte[b.Width*b.Height*4];for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++){var c=b.GetPixel(x,y);int n=(y*b.Width+x)*4;bytes[n]=c.B;bytes[n+1]=c.G;bytes[n+2]=c.R;bytes[n+3]=c.A;}return bytes;}}
 static void Pixels(byte[] bytes,int w,string name){Require(IsColor(bytes,w,60,20,2),name+" fixed cropped top-left retained red");Require(IsColor(bytes,w,20,20,1),name+" cropped left reveals green");Require(IsColor(bytes,w,180,70,2),name+" red half expands in place");Require(IsColor(bytes,w,250,70,0),name+" expanded right half blue");}
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application();preview=new LivePreview();var window=new Window{Title="TatsiaCraft isolated resize acceptance",Width=1000,Height=800,Content=preview};window.Loaded+=async(s,e)=>{try{
  string sourcePath=Path.Combine(root,"split.png"),greenPath=Path.Combine(root,"green.png");Fixture(sourcePath,320,180,true);Fixture(greenPath,800,600,false);var source=Engine.Probe(sourcePath);var green=Engine.Probe(greenPath);
  foreach(double rotation in new[]{0.0,90.0,33.0})foreach(bool native in new[]{true,false})foreach(var handle in new[]{new[]{0,0},new[]{1,0},new[]{2,0},new[]{0,1},new[]{2,1},new[]{0,2},new[]{1,2},new[]{2,2}}){
   int hx=handle[0],hy=handle[1];string label="rotation "+rotation+" native "+native+" handle "+hx+hy;
   var clip=new Clip{NativeSize=native,Scale=.7,X=17,Y=-13,Rotation=rotation,CropLeft=.125,CropTop=.1,CropRight=.2,CropBottom=.15};Setup(source,green,clip,800,600);await Task.Delay(12);Point anchor=Grip(2-hx,2-hy),drag=Grip(hx,hy);Vector offset=new Vector(3,-2);Point down=drag+offset;string before=json.Serialize(clip);var op=new CanvasResizeOperation(clip,Layer().Width,Layer().Height,800,600,hx,hy,down);var same=op.Evaluate(down);Near(same.Scale,.7,label+" offset pointer no scale jump");Near(same.X,17,label+" no X jump");Near(same.Y,-13,label+" no Y jump");var result=op.Evaluate(down+(drag-anchor)*.25);Require(json.Serialize(clip)==before,label+" pure evaluate preserves original clip");Near(result.Scale,.875,label+" proportional uniform scale");result.ApplyTo(clip);preview.Refresh();preview.UpdateLayout();Same(Grip(2-hx,2-hy),anchor,label+" rendered opposite visible anchor fixed");Same(Grip(hx,hy),drag+(drag-anchor)*.25,label+" rendered dragged handle reaches target");Near(clip.Rotation,rotation,label+" rotation unchanged");Require(clip.CropLeft==.125&&clip.CropTop==.1&&clip.CropRight==.2&&clip.CropBottom==.15,label+" all crop sides unchanged");
  }
  string referenceGreen=Path.Combine(root,"reference-green.png");Fixture(referenceGreen,320,180,false);green=Engine.Probe(referenceGreen);var c=new Clip{NativeSize=true,CropLeft=.125};var p=Setup(source,green,c,320,180);var corner=new CanvasResizeOperation(c,320,180,320,180,2,2,new Point(320,180));corner.Evaluate(new Point(460,270)).ApplyTo(c);Near(c.Scale,1.5,"reference bottom right scale");Near(c.X,60,"reference bottom right X");Near(c.Y,45,"reference bottom right Y");preview.Refresh();await Task.Delay(50);Same(Grip(0,0),new Point(40,0),"reference crop anchor");Pixels(PreviewPixels(320,180),320,"reference preview");Pixels(ExportPixels(p,"reference-resize"),320,"reference export");
  string saved=Path.Combine(root,"resized.tasia");Engine.Save(p,saved);var loaded=Engine.Load(saved);Near(loaded.Clips[1].Scale,1.5,"saved scale");Near(loaded.Clips[1].X,60,"saved X");Near(loaded.Clips[1].Y,45,"saved Y");Near(loaded.Clips[1].CropLeft,.125,"saved crop");Pixels(ExportPixels(loaded,"reopened-resize"),320,"reopened export");
  c=new Clip{NativeSize=true,CropLeft=.125};Setup(source,green,c,320,180);new CanvasResizeOperation(c,320,180,320,180,2,1,new Point(320,90)).Evaluate(new Point(400,90)).ApplyTo(c);Near(c.Scale,9.0/7,"reference side handle scale");Near(c.X,240.0/7,"reference side handle X");Near(c.Y,0,"reference side handle Y");preview.Refresh();Same(Grip(0,1),new Point(40,90),"reference side anchor fixed");
  c=new Clip{NativeSize=true,CropLeft=.5,Rotation=90};var rotatedProject=Setup(source,green,c,800,600);Point rotatedAnchor=Grip(0,0),rotatedDrag=Grip(2,2);new CanvasResizeOperation(c,320,180,800,600,2,2,rotatedDrag).Evaluate(rotatedDrag+(rotatedDrag-rotatedAnchor)*.5).ApplyTo(c);preview.Refresh();await Task.Delay(40);Same(Grip(0,0),rotatedAnchor,"rotated resized fixed crop corner");foreach(var rotatedPixels in new[]{PreviewPixels(800,600),ExportPixels(rotatedProject,"rotated-resize")}){Require(IsColor(rotatedPixels,800,350,400,0),"rotated resized retained blue location");Require(IsColor(rotatedPixels,800,350,270,1),"rotated resized cropped upper half reveals green");Require(IsColor(rotatedPixels,800,500,400,1),"rotated resized right boundary reveals green");} c=new Clip{NativeSize=true};Setup(source,green,c,800,600);Point a=Grip(0,0),d=Grip(2,2);var limits=new CanvasResizeOperation(c,320,180,800,600,2,2,d);var maximum=limits.Evaluate(d+(d-a)*10000);Near(maximum.Scale,8,"scale upper clamp");maximum.ApplyTo(c);preview.Refresh();Same(Grip(0,0),a,"upper clamp retains rendered anchor");c.Scale=1;c.X=c.Y=0;preview.Refresh();var minimum=limits.Evaluate(d-(d-a)*10);Near(minimum.Scale,.01,"scale lower clamp");minimum.ApplyTo(c);preview.Refresh();Same(Grip(0,0),a,"lower clamp retains rendered anchor");
  c=new Clip{NativeSize=true,X=32760};Setup(source,green,c,800,600);a=Grip(0,0);d=Grip(2,2);var bounded=new CanvasResizeOperation(c,320,180,800,600,2,2,d).Evaluate(d+(d-a)*10);Require(Math.Abs(bounded.X)<=32768&&Math.Abs(bounded.Y)<=32768,"position limits respected");bounded.ApplyTo(c);preview.Refresh();Same(Grip(0,0),a,"position limit retains rendered anchor");
  Reject(()=>new CanvasResizeOperation(null,320,180,800,600,2,2,new Point()),"null clip rejected");Reject(()=>new CanvasResizeOperation(new Clip(),0,180,800,600,2,2,new Point()),"zero source width rejected");Reject(()=>new CanvasResizeOperation(new Clip(),320,double.NaN,800,600,2,2,new Point()),"NaN source rejected");Reject(()=>new CanvasResizeOperation(new Clip(),320,180,double.PositiveInfinity,600,2,2,new Point()),"infinite project rejected");Reject(()=>new CanvasResizeOperation(new Clip(),320,180,800,600,1,1,new Point()),"center handle rejected");Reject(()=>new CanvasResizeOperation(new Clip(),320,180,800,600,3,1,new Point()),"invalid handle rejected");Reject(()=>new CanvasResizeOperation(new Clip(),320,180,800,600,2,2,new Point(double.NaN,0)),"invalid pointer down rejected");Reject(()=>limits.Evaluate(new Point(double.PositiveInfinity,0)),"invalid pointer update rejected");
  preview.Dispose();File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);app.Shutdown(0);
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);preview.Dispose();app.Shutdown(1);}};app.Run(window);}
}



